import { useState } from "react";
import Calculation from "../Calculation/Calculation";

import "./Appear.css";

function Appear() {
  let buttonArr = ["Calculation", "Data"];
  const [appear, setAppear] = useState(false);

  function showHide() {
    setAppear(!appear);
    whichAppear(!appear);
  }

  function whichAppear(value) {
    switch (value) {
      case true:
        console.log("a");
        return <Calculation />
      case false:
        console.log("b");
        return <p>a</p>
        break;
    }
  }

  return (
    <div className="mainAppear">
      <div className="buttons">
        {buttonArr.map((elm) => (
          <button key={elm} className="forAppear" onClick={showHide}>
            {elm}
          </button>
        ))}
      </div>
    </div>
  );
}

export default Appear;
